1	import { Pencil, Archive, Inbox } from "lucide-react";
2	import { Card, CardContent } from "@/components/ui/card";
3	import {
4	  Table,
5	  TableBody,
6	  TableCell,
7	  TableHead,
8	  TableHeader,
9	  TableRow,
10	} from "@/components/ui/table";
11	import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
