14	import { StatusBadge } from "@/components/inbox/status-badge";
15	import { PriorityBadge } from "@/components/inbox/priority-badge";
16	import { formatSlaChip, formatRelative } from "@/lib/utils/time";
17	import type { Request, Client, Assignee } from "@/lib/types";
18	
19	interface InboxTableProps {
20	  requests: readonly Request[];
21	  clients: readonly Client[];
22	  assignees: readonly Assignee[];
23	  onClearFilters?: () => void;
24	}
25	
26	function getInitials(name: string): string {
27	  return name
28	    .split(" ")
29	    .map((n) => n[0] ?? "")
30	    .slice(0, 2)
31	    .join("")
32	    .toUpperCase();
33	}
34	
35	function SlaChip({ slaDueAt }: { slaDueAt: string }) {
36	  const { label, tone } = formatSlaChip(slaDueAt);
37	  const colorClass =
38	    tone === "breached"
39	      ? "bg-red-100 text-red-700 ring-1 ring-red-200"
40	      : tone === "warning"
41	        ? "bg-amber-100 text-amber-700 ring-1 ring-amber-200"
42	        : "bg-muted text-muted-foreground ring-1 ring-border";
43	  return (
44	    <span
45	      className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${colorClass}`}
46	    >
47	      {label}
48	    </span>
49	  );
50	}
51	
52	export function InboxTable({
53	  requests,
54	  clients,
55	  assignees,
56	  onClearFilters,
57	}: InboxTableProps) {
58	  const clientMap = new Map(clients.map((c) => [c.id, c]));
59	  const assigneeMap = new Map(assignees.map((a) => [a.id, a]));
60	
61	  return (
62	    <Card className="overflow-hidden">
63	      <CardContent className="p-0">
64	        {requests.length === 0 ? (
65	          <EmptyState
66	            icon={Inbox}
67	            title="No matching requests"
68	            description="Try clearing your filters to see all requests."
69	            action={{ label: "Clear filters", onClick: onClearFilters }}
70	          />
71	        ) : (
72	          <>
73	            <Table>
74	              <TableHeader>
75	                <TableRow>
76	                  <TableHead className="pl-4 min-w-[200px]">Title</TableHead>
77	                  <TableHead className="min-w-[140px]">Client</TableHead>
78	                  <TableHead>Status</TableHead>
79	                  <TableHead className="hidden md:table-cell">Priority</TableHead>
80	                  <TableHead className="hidden md:table-cell">Assignee</TableHead>
81	                  <TableHead>SLA</TableHead>
82	                  <TableHead>Created</TableHead>
83	                  <TableHead className="w-20 text-right pr-4">Actions</TableHead>
84	                </TableRow>
85	              </TableHeader>
86	              <TableBody>
87	                {requests.map((req) => {
88	                  const client = clientMap.get(req.clientId);
89	                  const assignee = assigneeMap.get(req.assigneeId);
90	
91	                  return (
92	                    <TableRow
93	                      key={req.id}
94	                      className="cursor-pointer hover:bg-muted/30"
95	                      onClick={() => {
96	                        /* TODO(phase2): navigate to request detail */
97	                      }}
98	                    >
99	                      {/* Title */}
100	                      <TableCell className="pl-4 font-medium max-w-[240px]">
101	                        <span className="truncate block">{req.title}</span>
102	                      </TableCell>
103	
104	                      {/* Client */}
105	                      <TableCell>
106	                        {client ? (
107	                          <div className="flex items-center gap-2">
108	                            <Avatar size="sm">
109	                              <AvatarImage
110	                                src={client.avatarUrl}
111	                                alt={client.name}
112	                              />
113	                              <AvatarFallback>
114	                                {getInitials(client.name)}
115	                              </AvatarFallback>
116	                            </Avatar>
117	                            <span className="text-sm truncate max-w-[100px]">
118	                              {client.company}
119	                            </span>
120	                          </div>
121	                        ) : (
122	                          <span className="text-muted-foreground text-xs">—</span>
123	                        )}
124	                      </TableCell>
125	
126	                      {/* Status */}
127	                      <TableCell>
128	                        <StatusBadge status={req.status} />
129	                      </TableCell>
130	
131	                      {/* Priority — hidden on md and below */}
132	                      <TableCell className="hidden md:table-cell">
133	                        <PriorityBadge priority={req.priority} />
134	                      </TableCell>
135	
136	                      {/* Assignee — hidden on md and below */}
137	                      <TableCell className="hidden md:table-cell">
138	                        {assignee ? (
139	                          <div className="flex items-center gap-2">
140	                            <Avatar size="sm">
141	                              <AvatarImage
142	                                src={assignee.avatarUrl}
143	                                alt={assignee.name}
144	                              />
145	                              <AvatarFallback>
146	                                {getInitials(assignee.name)}
147	                              </AvatarFallback>
148	                            </Avatar>
149	                            <span className="text-xs text-muted-foreground truncate max-w-[80px]">
150	                              {assignee.name.split(" ")[0]}
151	                            </span>
152	                          </div>
153	                        ) : (
154	                          <span className="text-muted-foreground text-xs">—</span>
155	                        )}
156	                      </TableCell>
157	
158	                      {/* SLA */}
159	                      <TableCell>
160	                        <SlaChip slaDueAt={req.slaDueAt} />
161	                      </TableCell>
162	
163	                      {/* Created */}
164	                      <TableCell className="text-muted-foreground text-xs">
165	                        {formatRelative(req.createdAt)}
166	                      </TableCell>
167	
168	                      {/* Actions */}
169	                      <TableCell
170	                        className="text-right pr-4"
171	                        onClick={(e) => e.stopPropagation()}
172	                      >
173	                        <div className="flex items-center justify-end gap-1">
174	                          <Button
175	                            variant="ghost"
176	                            size="sm"
177	                            className="size-7 p-0"
178	                            aria-label="Edit request"
179	                            onClick={(e) => {
180	                              e.stopPropagation();
181	                              /* TODO(phase2): open edit dialog */
182	                            }}
183	                          >
184	                            <Pencil className="size-3.5" />
185	                          </Button>
186	                          <Button
187	                            variant="ghost"
188	                            size="sm"
189	                            className="size-7 p-0"
190	                            aria-label="Archive request"
191	                            onClick={(e) => {
192	                              e.stopPropagation();
193	                              /* TODO(phase2): archive request */
194	                            }}
195	                          >
196	                            <Archive className="size-3.5" />
197	                          </Button>
198	                        </div>
199	                      </TableCell>
200	                    </TableRow>
201	                  );
202	                })}
203	              </TableBody>
204	            </Table>
205	
206	            {/* Footer */}
207	            <div className="px-4 py-3 border-t text-xs text-muted-foreground">
208	              Showing {requests.length} of {requests.length}
209	            </div>
210	          </>
211	        )}
212	      </CardContent>
213	    </Card>
214	  );
215	}
