5	import { clients } from "@/lib/mock/clients";
6	import { getSlaStatus } from "@/lib/types";
7	import { EmptyState } from "@/components/common/empty-state";
8	
9	const ANCHOR = "2026-04-10T12:00:00Z";
10	
11	function formatSlaTime(slaDueAt: string): string {
12	  const dueMs = new Date(slaDueAt).getTime();
13	  const nowMs = new Date(ANCHOR).getTime();
14	  const diffHours = Math.round((dueMs - nowMs) / (1000 * 60 * 60));
15	  if (diffHours < 0) {
16	    return `${Math.abs(diffHours)}h overdue`;
17	  }
18	  return `due in ${diffHours}h`;
19	}
20	
21	const warningRequests = requests
22	  .filter((r) => {
23	    const status = getSlaStatus(r.slaDueAt);
24	    return status === "warning" || status === "breached";
25	  })
26	  .sort((a, b) => {
27	    const aStatus = getSlaStatus(a.slaDueAt);
28	    const bStatus = getSlaStatus(b.slaDueAt);
29	    if (aStatus === "breached" && bStatus !== "breached") return -1;
30	    if (bStatus === "breached" && aStatus !== "breached") return 1;
31	    return new Date(a.slaDueAt).getTime() - new Date(b.slaDueAt).getTime();
32	  })
33	  .slice(0, 4);
34	
35	export function SlaWarnings() {
36	  return (
37	    <Card className="shadow-card">
38	      <CardHeader className="pb-3">
39	        <CardTitle className="text-base font-semibold">SLA warnings</CardTitle>
40	        <p className="text-sm text-muted-foreground">
41	          Requests approaching or past deadline
42	        </p>
43	      </CardHeader>
44	      <CardContent>
45	        {warningRequests.length === 0 ? (
46	          <EmptyState
47	            icon={Clock}
48	            title="All clear"
49	            description="No SLA breaches right now"
50	          />
51	        ) : (
52	          <ul className="space-y-3">
53	            {warningRequests.map((req) => {
54	              const status = getSlaStatus(req.slaDueAt);
55	              const client = clients.find((c) => c.id === req.clientId);
56	              const timeLabel = formatSlaTime(req.slaDueAt);
57	
58	              return (
59	                <li key={req.id} className="flex items-center gap-3">
60	                  <span
61	                    className={`size-2 rounded-full shrink-0 ${
62	                      status === "breached"
63	                        ? "bg-rose-500"
64	                        : "bg-amber-400"
65	                    }`}
66	                  />
67	                  <div className="flex-1 min-w-0">
68	                    <p className="text-sm font-medium truncate">{req.title}</p>
69	                    <p className="text-xs text-muted-foreground">
70	                      {client?.company ?? "Unknown"} · {timeLabel}
71	                    </p>
72	                  </div>
73	                  <Button
74	                    variant="ghost"
75	                    size="sm"
76	                    className="shrink-0 h-7 px-2 text-xs"
77	                  >
78	                    View
79	                  </Button>
80	                </li>
81	              );
82	            })}
83	          </ul>
84	        )}
85	      </CardContent>
86	    </Card>
87	  );
88	}
