1	import { KanbanCard } from "@/components/inbox/kanban-card";
2	import type { Request, Client, Assignee, RequestStatus } from "@/lib/types";
3	
4	interface InboxKanbanProps {
5	  requests: readonly Request[];
6	  clients: readonly Client[];
7	  assignees: readonly Assignee[];
8	}
9	
10	const COLUMNS: readonly { id: RequestStatus; label: string }[] = [
11	  { id: "backlog", label: "Backlog" },
12	  { id: "in_progress", label: "In Progress" },
13	  { id: "review", label: "Review" },
14	  { id: "delivered", label: "Delivered" },
15	] as const;
16	
17	export function InboxKanban({ requests, clients, assignees }: InboxKanbanProps) {
18	  const clientMap = new Map(clients.map((c) => [c.id, c]));
19	  const assigneeMap = new Map(assignees.map((a) => [a.id, a]));
20	
21	  return (
22	    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
23	      {COLUMNS.map((col) => {
24	        const colRequests = requests.filter((r) => r.status === col.id);
25	
26	        return (
27	          <div key={col.id} className="rounded-xl bg-muted/30 p-3">
28	            {/* Column header */}
29	            <div className="flex items-center justify-between px-1 pb-3">
30	              <h3 className="text-sm font-semibold">{col.label}</h3>
31	              <span className="text-xs bg-muted rounded-full px-2 py-0.5">
32	                {colRequests.length}
33	              </span>
34	            </div>
35	
36	            {/* Column body */}
37	            <div className="max-h-[calc(100vh-20rem)] overflow-y-auto space-y-2 pr-1">
38	              {colRequests.length === 0 ? (
39	                <p className="text-xs text-muted-foreground text-center py-4">
40	                  No requests
41	                </p>
42	              ) : (
43	                colRequests.map((req) => (
44	                  <KanbanCard
45	                    key={req.id}
46	                    request={req}
47	                    client={clientMap.get(req.clientId)}
48	                    assignee={assigneeMap.get(req.assigneeId)}
49	                  />
50	                ))
51	              )}
52	            </div>
53	          </div>
54	        );
55	      })}
56	    </div>
57	  );
58	}
